style.css:
@-moz-document domain("youtube.com") {
/* Background */
    body, ytd-app {
        background-color: #ff66a3 !important; /* Vibrant Hot Pink */
        color: #000 !important; /* Black Text */
    }

    /* Header & Navigation */
    #masthead-container, #container, .ytd-masthead {
        background-color: #ff1493 !important; /* Deep Pink */
    }

    /* Sidebar & Menus */
    #guide-content, #sections, .ytd-guide-section-renderer {
        background-color: #ff99cc !important; /* Soft Neon Pink */
        color: #000 !important;
    }

    /* Video Thumbnails */
    ytd-thumbnail, .ytd-rich-grid-media {
        background-color: #ffccff !important; /* Light Pink */
        border-radius: 10px !important;
    }

    /* Buttons */
    .yt-spec-button-shape-next, .ytp-button {
        background-color: #ffcc00 !important; /* Neon Yellow */
        color: #000 !important;
        border-color: #ffcc00 !important;
    }

    /* Hover Effects */
    .yt-spec-button-shape-next:hover, .ytp-button:hover {
        background-color: #ffea00 !important; /* Bright Yellow */
    }

    /* Links */
    a {
        color: #ff0099 !important; /* Hot Pink */
    }

    /* Video Title Text */
    h1, h2, h3, .title, .ytd-video-primary-info-renderer {
        color: #000 !important; /* Black for strong contrast */
    }

    /* Progress Bar */
    .ytp-progress-bar {
        background-color: #ff0099 !important; /* Bright Pink */
    }

    /* Borders */
    .ytd-thumbnail, .yt-spec-button-shape-next {
        border: 2px solid #ffcc00 !important; /* Neon Yellow Borders */
    }

    /* Disable Text Selection */
    * {
        user-select: none !important;
        background-color: transparent !important;
        outline: none !important;
    }
}
